export function Logo({
  variant = 'full',
  tone = 'light',
  height = 28,
  style,
  title = 'Blackshop',
}: LogoProps): JSX.Element {
  const palette = PALETTE[tone];

  const mark = (
    <svg
      role="img"
      aria-label={title}
      viewBox="0 0 925 1037"
      height={height}
      xmlns="http://www.w3.org/2000/svg"
      style={{ flexShrink: 0, display: 'block' }}
    >
      <title>{title}</title>
      <path fill={palette.bag} d={BAG_PATH} />
      <path fill={palette.counter} d={B_PATH} />
    </svg>
  );

  if (variant === 'mark') {
    return <span style={style}>{mark}</span>;
  }

  const fontSize = height * 0.78;
  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: height * 0.24,
        lineHeight: 1,
        ...style,
      }}
      aria-label={title}
    >
      {mark}
      <span
        style={{
          fontFamily:
            'var(--font-sofia-sans), "Sofia Sans", system-ui, -apple-system, "Segoe UI", sans-serif',
          fontWeight: 800,
          fontSize: `${fontSize}px`,
          letterSpacing: '-0.028em',
          color: palette.word,
          lineHeight: 1,
          fontFeatureSettings: '"kern" 1, "liga" 1, "calt" 1',
          textRendering: 'geometricPrecision',
          WebkitFontSmoothing: 'antialiased',
        }}
      >
        Blackshop
      </span>
    </span>
  );
}
